package com.github.shannonbay.rereader.util

import android.graphics.Bitmap

/**
 * Implements document dewarping to correct page curl and geometric distortion.
 * Currently performs a dummy pass-through.
 */
class DewarpProcessor {

    /**
     * Processes the input bitmap to flatten the page.
     * @param original The captured photo of the document.
     * @return A dewarped [Bitmap] ready for OCR.
     */
    fun process(original: Bitmap): Bitmap {
        // Returning a copy to simulate a new bitmap being generated by the process
        val config = original.config ?: Bitmap.Config.ARGB_8888
        return original.copy(config, true)
    }
}